// packages/admin/lib/keccak.mjs
//
// Keccak-256 (the original Keccak padding, 0x01 ... 0x80, as Ethereum and the Safe contracts use;
// NOT FIPS-202 SHA3-256, which pads with 0x06). Node's crypto module has no Keccak-256, and the
// package takes no dependency, so the sponge is written here: pure, no import, BigInt lanes.
// Rate 136 bytes, capacity 512 bits, 24 rounds of Keccak-f[1600].

const MASK = (1n << 64n) - 1n
const rotl = (x, n) => (n === 0n ? x : ((x << n) | (x >> (64n - n))) & MASK)

// Round constants, generated by the spec's degree-8 LFSR; rotation offsets walk the (x,y) -> (y,2x+3y) path.
const RC = []
const ROT = new Array(25).fill(0n)
{
  let r = 1
  for (let i = 0; i < 24; i++) {
    let c = 0n
    for (let j = 0; j < 7; j++) {
      if (r & 1) c |= 1n << BigInt((1 << j) - 1)
      r = r & 0x80 ? ((r << 1) ^ 0x171) & 0xff : (r << 1) & 0xff
    }
    RC.push(c)
  }
  let x = 1
  let y = 0
  for (let t = 0; t < 24; t++) {
    ROT[x + 5 * y] = BigInt((((t + 1) * (t + 2)) / 2) % 64)
    ;[x, y] = [y, (2 * x + 3 * y) % 5]
  }
}

/** @param {bigint[]} s the 25 lanes, indexed x + 5y; permuted in place */
function permute(s) {
  for (let round = 0; round < 24; round++) {
    const C = []
    for (let x = 0; x < 5; x++) C[x] = s[x] ^ s[x + 5] ^ s[x + 10] ^ s[x + 15] ^ s[x + 20]
    for (let x = 0; x < 5; x++) {
      const D = C[(x + 4) % 5] ^ rotl(C[(x + 1) % 5], 1n)
      for (let y = 0; y < 25; y += 5) s[x + y] ^= D
    }
    const B = new Array(25)
    for (let x = 0; x < 5; x++) for (let y = 0; y < 5; y++) B[y + 5 * ((2 * x + 3 * y) % 5)] = rotl(s[x + 5 * y], ROT[x + 5 * y])
    for (let y = 0; y < 25; y += 5) for (let x = 0; x < 5; x++) s[x + y] = B[x + y] ^ (~B[((x + 1) % 5) + y] & B[((x + 2) % 5) + y] & MASK)
    s[0] ^= RC[round]
  }
}

/**
 * @param {Uint8Array} input
 * @returns {Uint8Array} the 32-byte Keccak-256 digest
 */
export function keccak256(input) {
  const RATE = 136
  const padded = new Uint8Array(Math.ceil((input.length + 1) / RATE) * RATE)
  padded.set(input)
  padded[input.length] ^= 0x01
  padded[padded.length - 1] ^= 0x80
  const s = new Array(25).fill(0n)
  for (let off = 0; off < padded.length; off += RATE) {
    for (let i = 0; i < RATE / 8; i++) {
      let lane = 0n
      for (let b = 7; b >= 0; b--) lane = (lane << 8n) | BigInt(padded[off + i * 8 + b])
      s[i] ^= lane
    }
    permute(s)
  }
  const out = new Uint8Array(32)
  for (let i = 0; i < 32; i++) out[i] = Number((s[i >> 3] >> BigInt(8 * (i & 7))) & 0xffn)
  return out
}
